26	@Service
27	public class OrderService {
28	
29	    public record ItemCommand(long productId, long quantity) {
30	    }
31	
32	    /** A committed 2xx response: status, serialized body (also stored as the idempotency snapshot), id. */
33	    public record Written(int status, String body, long orderId) {
34	    }
35	
36	    private enum PayOutcome { OK, DECLINED, EXPIRED }
37	
38	    private record PayResult(PayOutcome outcome, Written written) {
39	    }
40	
41	    private final OrderRepository orders;
42	    private final ProductRepository products;
43	    private final CouponRepository coupons;
44	    private final ReservationReleaser releaser;
45	    private final ExpiryService expiry;
46	    private final IdempotencyService idempotency;
47	    private final PaymentGatewayClient gateway;
48	    private final ObjectMapper mapper;
49	    private final TransactionTemplate tx;
50	    private final Duration paymentTtl;
51	
52	    public OrderService(OrderRepository orders, ProductRepository products, CouponRepository coupons,
53	            ReservationReleaser releaser, ExpiryService expiry, IdempotencyService idempotency,
54	            PaymentGatewayClient gateway, ObjectMapper mapper, PlatformTransactionManager tm,
55	            @Value("${app.order-payment-ttl}") String paymentTtl) {
56	        this.orders = orders;
57	        this.products = products;
58	        this.coupons = coupons;
59	        this.releaser = releaser;
60	        this.expiry = expiry;
61	        this.idempotency = idempotency;
62	        this.gateway = gateway;
63	        this.mapper = mapper;
64	        this.tx = new TransactionTemplate(tm);
65	        this.paymentTtl = Duration.parse(paymentTtl.trim());
66	    }
67	
68	    // ---------------------------------------------------------------- create (R3, R2.4-R2.6)
69	
70	    public Written create(String userId, List<ItemCommand> items, String couponCode, String idemKey) {
71	        expiry.expireDue();
72	        return tx.execute(s -> {
73	            // 404 first (C3)
74	            for (ItemCommand item : items) {
75	                if (!products.exists(item.productId())) {
76	                    throw ApiException.notFound("PRODUCT_NOT_FOUND", "product " + item.productId() + " not found");
77	                }
78	            }
79	            if (couponCode != null && coupons.find(couponCode).isEmpty()) {
80	                throw ApiException.notFound("COUPON_NOT_FOUND", "coupon " + couponCode + " not found");
81	            }
82	
83	            // lock products in ascending id order (deadlock-free), then the coupon
84	            Map<Long, Product> locked = new TreeMap<>();
85	            items.stream().map(ItemCommand::productId).sorted().forEach(id -> locked.put(id, products.lock(id)));
86	
87	            for (ItemCommand item : items) {
88	                if (locked.get(item.productId()).available() < item.quantity()) {
89	                    throw ApiException.conflict("INSUFFICIENT_STOCK",
90	                            "insufficient stock for product " + item.productId());
91	                }
92	            }
93	
94	            List<Order.Item> lines = new ArrayList<>();
95	            long subtotal = 0;
96	            for (ItemCommand item : items) {
97	                long price = locked.get(item.productId()).price();
98	                lines.add(new Order.Item(item.productId(), item.quantity(), price));
99	                subtotal = Math.addExact(subtotal, Math.multiplyExact(price, item.quantity()));
100	            }
101	
102	            OffsetDateTime now = Times.now();
103	            long discount = 0;
104	            if (couponCode != null) {
105	                Coupon coupon = coupons.lock(couponCode);
106	                if (!coupon.isValidAt(now) || subtotal < coupon.minOrderAmount()
107	                        || orders.userHasActiveCouponOrder(userId, couponCode)) {
108	                    throw ApiException.conflict("COUPON_NOT_APPLICABLE",
109	                            "coupon " + couponCode + " cannot be applied to this order");
110	                }
111	                if (coupon.usedCount() >= coupon.totalQuantity()) {
112	                    throw ApiException.conflict("COUPON_EXHAUSTED", "coupon " + couponCode + " is exhausted");
113	                }
114	                discount = coupon.discountFor(subtotal);
115	            }
116	
117	            locked.forEach((id, p) -> products.addReserved(id, quantityOf(items, id)));
118	            if (couponCode != null) {
119	                coupons.addUsed(couponCode, 1);
120	            }
121	            long id = orders.insert(userId, couponCode, subtotal, discount, subtotal - discount, now,
122	                    Times.normalize(now.plus(paymentTtl)), lines);
123	            String body = json(orders.find(id).orElseThrow());
124	            idempotency.complete(IdempotencyService.SCOPE_CREATE_ORDER, idemKey, 201, body, location(id));
125	            return new Written(201, body, id);
126	        });
127	    }
128	
129	    private static long quantityOf(List<ItemCommand> items, long productId) {
130	        return items.stream().filter(i -> i.productId() == productId).mapToLong(ItemCommand::quantity).sum();
131	    }
132	
133	    public static String location(long id) {
134	        return "/api/orders/" + id;
135	    }
136	
137	    // ---------------------------------------------------------------- pay (R5)
138	
139	    /**
140	     * The order row stays locked (SELECT ... FOR UPDATE) for the whole PG call, so concurrent payments of the same
141	     * order are serialized and at most one reaches the PG (R10.5). PG failure throws 503 and rolls back: no change.
142	     */
143	    public Written pay(long orderId, String cardToken, String idemKey) {
144	        PayResult result = tx.execute(s -> {
145	            Order order = orders.lock(orderId).orElseThrow(() -> orderNotFound(orderId));
146	            if (order.status() != OrderStatus.PENDING_PAYMENT) {
147	                throw ApiException.invalidState("order " + orderId + " is " + order.status());
148	            }
149	            if (!Times.now().isBefore(order.expiresAt())) {
150	                expiry.expire(order);
151	                return new PayResult(PayOutcome.EXPIRED, null);
152	            }
153	            String paymentId = null;
154	            if (order.totalPrice() > 0) {
155	                PaymentResult pg = gateway.pay(order.id(), order.totalPrice(), cardToken, idemKey);
156	                if (pg.status() == PaymentGatewayClient.PaymentStatus.DECLINED) {
157	                    releaser.releaseReservation(order);
158	                    orders.updateStatus(order.id(), OrderStatus.PAYMENT_FAILED);
159	                    return new PayResult(PayOutcome.DECLINED, null);
160	                }
161	                paymentId = pg.paymentId();
162	            }
163	            releaser.consumeReservation(order);
164	            orders.markPaid(order.id(), Times.now(), paymentId);
165	            String body = json(orders.find(order.id()).orElseThrow());
166	            idempotency.complete(IdempotencyService.SCOPE_PAY, idemKey, 200, body, null);
167	            return new PayResult(PayOutcome.OK, new Written(200, body, order.id()));
168	        });
169	        return switch (result.outcome()) {
170	            case OK -> result.written();
171	            case DECLINED -> throw new ApiException(HttpStatus.PAYMENT_REQUIRED, "PAYMENT_DECLINED",
172	                    "payment for order " + orderId + " was declined");
173	            case EXPIRED -> throw ApiException.invalidState("order " + orderId + " has expired");
174	        };
175	    }
176	
177	    // ---------------------------------------------------------------- cancel / refund (R7)
178	
179	    public String cancel(long orderId) {
180	        Object result = tx.execute(s -> {
181	            Order order = orders.lock(orderId).orElseThrow(() -> orderNotFound(orderId));
182	            switch (order.status()) {
183	                case PENDING_PAYMENT -> {
184	                    if (!Times.now().isBefore(order.expiresAt())) {
185	                        expiry.expire(order);
186	                        return Boolean.FALSE;
187	                    }
188	                    releaser.releaseReservation(order);
189	                    orders.updateStatus(order.id(), OrderStatus.CANCELLED);
190	                }
191	                case PAID -> {
192	                    if (order.paymentId() != null) {
193	                        gateway.refund(order.paymentId());
194	                    }
195	                    releaser.returnStock(order);
196	                    orders.updateStatus(order.id(), OrderStatus.REFUNDED);
197	                }
198	                default -> throw ApiException.invalidState("order " + orderId + " is " + order.status());
199	            }
200	            return json(orders.find(order.id()).orElseThrow());
201	        });
202	        if (Boolean.FALSE.equals(result)) {
203	            throw ApiException.invalidState("order " + orderId + " has expired");
204	        }
205	        return (String) result;
206	    }
