218	    private String transition(long orderId, OrderStatus from, OrderStatus to) {
219	        expiry.expireDue();
220	        return tx.execute(s -> {
221	            Order order = orders.lock(orderId).orElseThrow(() -> orderNotFound(orderId));
222	            if (order.status() != from) {
223	                throw ApiException.invalidState("order " + orderId + " is " + order.status());
224	            }
225	            orders.updateStatus(order.id(), to);
226	            return json(orders.find(order.id()).orElseThrow());
227	        });
228	    }
