                plan.fullyRefunded() ? OrderStatus.REFUNDED : OrderStatus.PARTIALLY_REFUNDED);
    }

    /** P4.2-P4.4: every requested line must be in the order and within its remaining units. */
    private static Map<Long, Long> requestedQuantities(Order order, List<ItemCommand> items) {
        Map<Long, Long> requested = new TreeMap<>();
